18	
19	/**
20	 * Raised when a new owner is submitted with a normalized telephone number that is already used by an
21	 * existing owner, so the client can be told the value conflicts with another record.
22	 */
23	public class DuplicateTelephoneException extends RuntimeException {
24	
25	    private final String telephone;
26	
27	    public DuplicateTelephoneException(String telephone) {
28	        super("Telephone is already used by another owner: " + telephone);
29	        this.telephone = telephone;
30	    }
31	
32	    public String getTelephone() {
33	        return this.telephone;
34	    }
35	}
