17	package org.springframework.samples.petclinic.rest.validation;
18	
19	/**
20	 * Raised when a new owner is submitted whose last name and address already belong to another owner
21	 * (compared case-insensitively with collapsed whitespace), so the client can be told the record
22	 * conflicts with an existing household. The client may override this by opting in with
23	 * {@code sharesHousehold}.
24	 */
25	public class DuplicateHouseholdException extends RuntimeException {
26	
27	    private final String lastName;
28	
29	    private final String address;
30	
31	    public DuplicateHouseholdException(String lastName, String address) {
32	        super("An owner with the same last name and address already exists: " + lastName + ", " + address);
33	        this.lastName = lastName;
34	        this.address = address;
35	    }
36	
37	    public String getLastName() {
38	        return this.lastName;
39	    }
40	
41	    public String getAddress() {
42	        return this.address;
43	    }
44	}
