132	    /**
133	     * Handles exception thrown by Bean Validation on controller methods parameters
134	     *
135	     * @param e The {@link MethodArgumentNotValidException} to be handled
136	     * @param request {@link HttpServletRequest} object referring to the current request.
137	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
138	     */
139	    @ExceptionHandler(MethodArgumentNotValidException.class)
140	    @ResponseBody
141	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
142	        HttpStatus status = HttpStatus.BAD_REQUEST;
143	        BindingErrorsResponse errors = new BindingErrorsResponse();
144	        BindingResult bindingResult = e.getBindingResult();
145	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
146	        if (bindingResult.hasErrors()) {
147	            errors.addAllErrors(bindingResult);
148	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
149	                .map(fieldError -> {
150	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
151	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
152	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
153	                        fieldError.getField(),
154	                        defaultMessage,
155	                        rejectedValue);
156	                    return new ValidationMessageDto(message)
157	                        .putAdditionalProperty("field", fieldError.getField())
158	                        .putAdditionalProperty("rejectedValue", rejectedValue)
159	                        .putAdditionalProperty("defaultMessage", defaultMessage);
160	                })
161	                .toList();
162	            logger.debug("Validation error at {} {}: {}",
163	                request.getMethod(),
164	                request.getRequestURI(),
165	                bindingResult.getFieldErrors());
166	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
167	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
168	                .map(FieldError::getField)
169	                .distinct()
170	                .toList();
171	            detail.setProperty("errors", invalidFields);
172	            return ResponseEntity.status(status).body(detail);
173	        }
174	        return ResponseEntity.status(status).body(detail);
175	    }
